--
-- Name: vehicle_inspections; Type: TABLE; Schema: public; Owner: emerald_owner
--

CREATE TABLE public.vehicle_inspections (
    id integer NOT NULL,
    vehicle_id integer NOT NULL,
    technician_id integer NOT NULL,
    inspection_date date NOT NULL,
    km_actual integer NOT NULL,
    water_level_ok boolean DEFAULT true NOT NULL,
    oil_level_ok boolean DEFAULT true NOT NULL,
    tires_ok boolean DEFAULT true NOT NULL,
    lights_ok boolean DEFAULT true NOT NULL,
    cleanliness_ok boolean DEFAULT true NOT NULL,
    damage_notes text,
    status character varying(20) DEFAULT 'OK'::character varying NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    mechanical_conditions text,
    oil_level character varying(10) DEFAULT 'medio'::character varying NOT NULL,
    water_level character varying(10) DEFAULT 'medio'::character varying NOT NULL,
    fuel_level character varying(10) DEFAULT 'medio'::character varying NOT NULL,
    brake_fluid_level character varying(10) DEFAULT 'medio'::character varying NOT NULL,
    has_hydraulic_leaks boolean DEFAULT false NOT NULL,
    pulls_to_one_side boolean DEFAULT false NOT NULL,
    oil_leaks boolean DEFAULT false NOT NULL,
    hose_leaks boolean DEFAULT false NOT NULL,
    radiator_leaks boolean DEFAULT false NOT NULL,
    low_beam_lights_ok boolean DEFAULT true NOT NULL,
    high_beam_lights_ok boolean DEFAULT true NOT NULL,
    hazard_lights_ok boolean DEFAULT true NOT NULL,
    brake_lights_ok boolean DEFAULT true NOT NULL,
    position_lights_ok boolean DEFAULT true NOT NULL,
    reverse_lights_ok boolean DEFAULT true NOT NULL,
    fog_lights_ok boolean DEFAULT true NOT NULL,
    dashboard_indicators_on boolean DEFAULT false NOT NULL,
    reverse_alarm_ok boolean DEFAULT true NOT NULL,
    tires_cuts_or_bulges boolean DEFAULT false NOT NULL,
    has_spare_tire boolean DEFAULT true NOT NULL,
    has_lug_wrench boolean DEFAULT true NOT NULL,
    has_jack boolean DEFAULT true NOT NULL,
    tires_pressure_ok_30psi boolean DEFAULT true NOT NULL,
    seatbelts_all_ok boolean DEFAULT true NOT NULL,
    horn_ok boolean DEFAULT true NOT NULL,
    mirrors_ok boolean DEFAULT true NOT NULL,
    has_two_safety_cones boolean DEFAULT true NOT NULL,
    fire_extinguisher_ok boolean DEFAULT true NOT NULL,
    wipers_ok boolean DEFAULT true NOT NULL,
    CONSTRAINT ck_vehicle_inspections_brake_fluid_level_values CHECK (((brake_fluid_level)::text = ANY (ARRAY[('bajo'::character varying)::text, ('minimo'::character varying)::text, ('medio'::character varying)::text, ('alto'::character varying)::text]))),
    CONSTRAINT ck_vehicle_inspections_fuel_level_values CHECK (((fuel_level)::text = ANY (ARRAY[('bajo'::character varying)::text, ('minimo'::character varying)::text, ('medio'::character varying)::text, ('alto'::character varying)::text]))),
    CONSTRAINT ck_vehicle_inspections_km_non_negative CHECK ((km_actual >= 0)),
    CONSTRAINT ck_vehicle_inspections_oil_level_values CHECK (((oil_level)::text = ANY (ARRAY[('bajo'::character varying)::text, ('minimo'::character varying)::text, ('medio'::character varying)::text, ('alto'::character varying)::text]))),
    CONSTRAINT ck_vehicle_inspections_status_values CHECK (((status)::text = ANY (ARRAY[('OK'::character varying)::text, ('NEEDS_ATTENTION'::character varying)::text, ('CRITICAL'::character varying)::text]))),
    CONSTRAINT ck_vehicle_inspections_water_level_values CHECK (((water_level)::text = ANY (ARRAY[('bajo'::character varying)::text, ('minimo'::character varying)::text, ('medio'::character varying)::text, ('alto'::character varying)::text])))
);


